import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition custom CUDA operator ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Matrix multiplication custom CUDA operator ----------
# Kernel for single-element GEMM (naive but functional)
matmul_kernel_source = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= M * N) return;
    int i = idx / N;
    int j = idx % N;
    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        sum += A[i * K + k] * B[k * N + j];
    }
    C[idx] = sum;
}
"""

matmul_cuda_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto sizeA = A.numel();
    auto out = torch::zeros_like(A);

    const int M = A.shape()[0];
    const int N = A.shape()[1];
    const int K = A.shape()[1]; // for square matrices, inner dimension equals N

    const int blockSize = 256;
    const int numBlocks = (sizeA + blockSize - 1) / blockSize;

    matmul_kernel<<<numBlocks, blockSize>>> (A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float()>, M, N, K);

    return out;
}
"""

elementmatmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_source = matmul_kernel_source + "\n\n" + matmul_cuda_source

matmul = load_inline(
    name="matmul",
    cpp_sources=elementmatmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Optimized model ----------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul = matmul

    def forward(self, A, B):
        return self.matmul.matmul_cuda(A, B)
